#define ELEMENT_RATING 0x282deUL
#define ODDS           0x282a4UL
#define UNIT_DIRECTION 0x2808eUL
#define CAN_ENTER      0x283ecUL
#define RAND_BOUNDED   0x0a034UL
#define PATH_FLOOD     0x2a5b0UL
